  flex-wrap: wrap;
  gap: 10px;
  justify-content: center;
}

.EndevSponsorsError {
  color: var(--vp-c-text-3);
  font-size: 13px;
  font-weight: 500;
  margin: 0;
}

.EndevSponsorsLogo {
