  color: #000;
  font-size: 0.9rem;
  line-height: 1.4;
  text-align: center;
}
.jdx-banner a {
  color: #000;
  text-decoration: underline;
  font-weight: 600;
}
.jdx-banner button {
  position: absolute;
  right: 0.5rem;
  top: 50%;
  transform: translateY(-50%);
  background: transparent;
  border: 0;
  color: inherit;
  font-size: 1.25rem;
  cursor: pointer;
  line-height: 1;
  padding: 0 0.5rem;
  opacity: 0.7;
}
.jdx-banner button:hover {
  opacity: 1;
}
@media (max-width: 640px) {
  .jdx-banner {
    flex-direction: column;
    gap: 0.125rem;
    font-size: 0.8rem;
    padding: 0.5rem 2.25rem;
    line-height: 1.3;
    text-wrap: balance;
  }
  .jdx-banner button {
    top: 0.25rem;
    right: 0.25rem;
    transform: none;
  }
}

