      localStorage.setItem(STORAGE_KEY, currentBanner.id);
    } catch {
      // Dismiss for this page even when localStorage is unavailable.
    }
    removeActiveBanner();
    clearReserved();
  });
  el.appendChild(btn);

  document.body.prepend(el);
  activeBanner = {
    id: b.id,
    element: el,
    observer,
    update,
    cancelExpiration,
  };
  scheduleExpiration();

  requestAnimationFrame(syncHeight);
  observer?.observe(el);
}
